; b05_done_error -- Peri reports a good service, then a failed one; Main branches on PERI_NO_ERROR / PERI_ERROR
; Layer-2 conformance test (generated by conformance/make_conformance.py: edit that, not this file).
; Checks: PERI_NO_ERROR = done and no error, PERI_ERROR = done and error; the service reset clears both latches
; Results go to the result CSRs RES + n (conf_defs.inc); the last write is RES_DONE = 0xA5. Expected values: b05_done_error.expected.csv
.include "conf_defs.inc"
.include "conf_board.inc"                      ; the CSRs of the board: put YOUR addresses and bits there first
.equ T_GAP = 60000                           ; ticks between the two services
.devmap 0, I2C, 0x2B, DEV_GOOD
.devmap 1, I2C, 0x2D, DEV_ABSENT          ; NO device answers at this address on the bench
.main
w1:
    BR.COND PERI_NO_ERROR, good                ; the first service ends well
    BR.COND PERI_ERROR, early
    JMP w1
early:
    EXEC_CSR WRITE8 RES + 0, 0xEE              ; (not expected: an error before the good service)
    JMP w2
good:
    EXEC_CSR WRITE8 RES + 0, 0x0A
w2:
    BR.COND PERI_ERROR, bad                    ; the second service fails
    JMP w2
bad:
    EXEC_CSR WRITE8 RES + 1, 0xEB
    EXEC_CSR WRITE8 RES_DONE, 0xA5          ; the last write: everything above is there
done:
    JMP done
.peri
    EXEC_CSR SET8 PERI_CTRL, PERI_RESET        ; service 1: a transfer that works
    EXEC_XFER READ dev=DEV_GOOD, addr=0x40, addrlen=1, ptr=0
    EXEC_CSR SET8 PERI_CTRL, PERI_DONE
    EXEC_CSR WRITE8 PERI_TPER,   T_GAP & 0xFF  ; leave Main the time to see it
    EXEC_CSR WRITE8 PERI_TPER_H, T_GAP >> 8
    EXEC_CSR SET8 PERI_CTRL, PERI_TIMER_START
gap:
    BR.IF_TIMER_DONE gap_done
    JMP gap
gap_done:
    EXEC_CSR SET8 PERI_CTRL, PERI_RESET        ; service 2: nobody answers
    EXEC_XFER READ dev=DEV_ABSENT, addr=0x00, addrlen=1, ptr=0
    EXEC_CSR SET8 PERI_CTRL, PERI_DONE
phalt:
    JMP phalt
